using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.Discount;

public class DiscountAcceptanceTests
{
    // Bronze customer is charged the Bronze price
    [Fact]
    public void S1_BronzeBasketIsCharged9500Cents()
    {
        var quote = new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Bronze));

        Assert.Equal(9500, quote.TotalCents);
    }

    // Silver customer is charged the Silver price
    [Fact]
    public void S2_SilverBasketIsCharged9000Cents()
    {
        var quote = new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Silver));

        Assert.Equal(9000, quote.TotalCents);
    }

    // Gold customer is charged the Gold price
    [Fact]
    public void S3_GoldBasketIsCharged8500Cents()
    {
        var quote = new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(10000, LoyaltyTier.Gold));

        Assert.Equal(8500, quote.TotalCents);
    }

    // Bronze customer with a tiny basket is charged a whole cent in their favour
    [Fact]
    public void S4_BronzeTinyBasketIsCharged7Cents()
    {
        var quote = new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(7, LoyaltyTier.Bronze));

        Assert.Equal(7, quote.TotalCents);
    }
}

